import json

def find_h_segments(grid):
    """Find all h-segment (horizontal segment) cells in the grid"""
    h_segment_cells = []
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    for r in range(rows):
        for c in range(cols):
            if c > 0 and c < cols - 1:
                if grid[r][c] == 0 and grid[r][c-1] == 0 and grid[r][c+1] == 0:
                    h_segment_cells.append((r, c))
    return h_segment_cells

def get_h_segment_rows_per_col(grid):
    """Get h-segment rows for each column"""
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    h_seg_rows_per_col = {}

    for c in range(cols):
        h_segs = []
        for r in range(rows):
            if c > 0 and c < cols - 1:
                if grid[r][c] == 0 and grid[r][c-1] == 0 and grid[r][c+1] == 0:
                    h_segs.append(r)
        h_seg_rows_per_col[c] = tuple(sorted(h_segs))

    return h_seg_rows_per_col

def find_unique_column_patterns(grid):
    """Find columns with unique h-segment patterns"""
    h_seg_rows_per_col = get_h_segment_rows_per_col(grid)

    from collections import Counter
    pattern_counts = Counter()
    for pattern in h_seg_rows_per_col.values():
        pattern_counts[pattern] += 1

    unique_patterns = {p for p, count in pattern_counts.items() if count == 1}

    unique_cols = [c for c, pattern in h_seg_rows_per_col.items() if pattern in unique_patterns]

    return h_seg_rows_per_col, unique_cols

def fill_between_h_segments(grid, col, h_seg_rows):
    """Fill 9s between consecutive h-segment rows in a column with 4s"""
    fill_positions = []
    rows = len(grid)

    for i in range(len(h_seg_rows) - 1):
        top_row = h_seg_rows[i]
        bot_row = h_seg_rows[i + 1]
        for r in range(top_row + 1, bot_row):
            if grid[r][col] == 9:
                fill_positions.append((r, col))

    return fill_positions

# Test the transformation
def transform(grid):
    """Transform grid by filling 9s with 4s between h-segments in unique-pattern columns"""
    import copy
    result = copy.deepcopy(grid)

    h_seg_rows_per_col, unique_cols = find_unique_column_patterns(grid)

    for col in unique_cols:
        h_seg_rows = h_seg_rows_per_col[col]
        fill_positions = fill_between_h_segments(grid, col, h_seg_rows)

        for r, c in fill_positions:
            result[r][c] = 4

    return result

